require_once __DIR__.'/../../includes/inventario.php'; exigir_inventario_admin(); validar_post_csrf();$db=obtener_conexion();$error='';$alerta='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$material=(int)($_POST['id_material']??0);$tipo=(string)($_POST['tipo']??'');$cantidad=$_POST['cantidad']??null;$fecha=str_replace('T',' ',(string)($_POST['fecha']??date('Y-m-d H:i:s')));if($material<1||!in_array($tipo,['entrada','salida'],true)||!decimal_positivo($cantidad))throw new InvalidArgumentException('Material, tipo y cantidad mayor que cero son obligatorios.');$cantidad=(float)$cantidad;$db->beginTransaction();$s=$db->prepare('SELECT stock,stock_minimo,nombre FROM material WHERE id_material=? FOR UPDATE');$s->execute([$material]);$m=$s->fetch();if(!$m)throw new InvalidArgumentException('Material no encontrado.');if($tipo==='salida'&&$cantidad>(float)$m['stock'])throw new InvalidArgumentException('La salida no puede superar el stock disponible.');$nuevo=$tipo==='entrada'?(float)$m['stock']+$cantidad:(float)$m['stock']-$cantidad;$db->prepare('UPDATE material SET stock=? WHERE id_material=?')->execute([$nuevo,$material]);$db->prepare('INSERT INTO movimiento_inventario(id_material,id_usuario,tipo,cantidad,fecha) VALUES(?,?,?,?,?)')->execute([$material,$_SESSION['usuario']['id_usuario'],$tipo,$cantidad,$fecha]);$db->commit();registrar_bitacora('movimiento_inventario',$tipo.' '.$cantidad.' material '.$material);if($tipo==='salida'&&$nuevo<=(float)$m['stock_minimo'])$alerta='Alerta: '.$m['nombre'].' quedó en el nivel mínimo o por debajo.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo registrar el movimiento.';}}
$material_filtro=(int)($_GET['id_material']??0);$desde=(string)($_GET['desde']??'');$hasta=(string)($_GET['hasta']??'');$pagina=max(1,(int)($_GET['pagina']??1));$limite=10;$offset=($pagina-1)*$limite;$cond=[];$params=[];if($material_filtro){$cond[]='mi.id_material=?';$params[]=$material_filtro;}if($desde!==''){$cond[]='mi.fecha>=?';$params[]=$desde.' 00:00:00';}if($hasta!==''){$cond[]='mi.fecha<=?';$params[]=$hasta.' 23:59:59';}$where=$cond?' WHERE '.implode(' AND ',$cond):'';$s=$db->prepare('SELECT COUNT(*) FROM movimiento_inventario mi'.$where);$s->execute($params);$total=(int)$s->fetchColumn();$s=$db->prepare('SELECT mi.*,m.nombre AS material_nombre,u.nombre AS usuario_nombre FROM movimiento_inventario mi INNER JOIN material m ON m.id_material=mi.id_material INNER JOIN usuario u ON u.id_usuario=mi.id_usuario'.$where.' ORDER BY mi.fecha DESC,mi.id_movimiento DESC LIMIT '.$limite.' OFFSET '.$offset);$s->execute($params);$movimientos=$s->fetchAll();$materiales=$db->query('SELECT id_material,nombre,stock FROM material ORDER BY nombre')->fetchAll();$titulo='Movimientos de inventario';require __DIR__.'/../../includes/header.php';?>
