<section class="card mb-4"><div class="card-header"><h3><i class="bi bi-box-arrow-in-down"></i> Registrar entrada o salida</h3></div><div class="card-body"><form method="post" onsubmit="return validarCantidadInventario()"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-12 col-lg-5"><label class="form-label">Material <span class="required">*</span></label><select class="form-select" name="id_material" required><option value="">Selecciona</option><?php foreach($materiales as $m): ?><option value="<?=$m['id_material']?>"><?=e($m['nombre'])?> (stock: <?=e((string)$m['stock'])?>)</option><?php endforeach; ?></select></div><div class="col-12 col-md-4 col-lg-2"><label class="form-label">Tipo <span class="required">*</span></label><select class="form-select" name="tipo" required><option value="entrada">Entrada</option><option value="salida">Salida</option></select></div><div class="col-12 col-md-4 col-lg-2"><label class="form-label" for="cantidad-inventario">Cantidad <span class="required">*</span></label><input class="form-control" id="cantidad-inventario" type="number" name="cantidad" min="0.01" step="0.01" required></div><div class="col-12 col-md-4 col-lg-3"><label class="form-label">Fecha</label><input class="form-control" type="datetime-local" name="fecha" value="<?=date('Y-m-d\TH:i')?>" required></div></div><div class="form-actions"><button class="btn btn-primary" type="submit"><i class="bi bi-check2-circle"></i> Guardar movimiento</button></div></form></div></section>
<section class="card mb-4"><div class="card-body"><form class="row g-2 align-items-end" method="get"><div class="col-12 col-md-4"><label class="form-label">Material</label><select class="form-select" name="id_material"><option value="">Todos los materiales</option><?php foreach($materiales as $m): ?><option value="<?=$m['id_material']?>" <?=$material_filtro===$m['id_material']?'selected':''?>><?=e($m['nombre'])?></option><?php endforeach; ?></select></div><div class="col-12 col-md-3"><label class="form-label">Desde</label><input class="form-control" type="date" name="desde" value="<?=e($desde)?>"></div><div class="col-12 col-md-3"><label class="form-label">Hasta</label><input class="form-control" type="date" name="hasta" value="<?=e($hasta)?>"></div><div class="col-12 col-md-2 d-grid"><button class="btn btn-primary" type="submit"><i class="bi bi-funnel"></i> Filtrar</button></div></form></div></section>
<section class="card table-card"><div class="card-header"><h3><i class="bi bi-clock-history"></i> Historial de movimientos</h3></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Fecha</th><th>Material</th><th>Tipo</th><th class="stock">Cantidad</th><th>Usuario</th></tr></thead><tbody><?php foreach($movimientos as $m): ?><tr><td><?=e($m['fecha'])?></td><td><?=e($m['material_nombre'])?></td><td><span class="badge <?=$m['tipo']==='entrada'?'bg-success':'bg-danger'?>"><?=e(ucfirst($m['tipo']))?></span></td><td class="stock"><?=e((string)$m['cantidad'])?></td><td><?=e($m['usuario_nombre'])?></td></tr><?php endforeach; ?><?php if(!$movimientos): ?><tr><td colspan="5"><div class="empty-state"><i class="bi bi-arrow-left-right"></i><p>No hay movimientos para los filtros indicados.</p></div></td></tr><?php endif; ?></tbody></table></div><?php $paginas=max(1,(int)ceil($total/$limite)); if($paginas>1): ?><nav aria-label="Paginación"><ul class="pagination"><?php for($i=1;$i<=$paginas;$i++): ?><li class="page-item <?=$i===$pagina?'active':''?>"><a class="page-link" href="?id_material=<?=$material_filtro?>&desde=<?=urlencode($desde)?>&hasta=<?=urlencode($hasta)?>&pagina=<?=$i?>"><?=$i?></a></li><?php endfor; ?></ul></nav><?php endif; ?></section>
<script>function validarCantidadInventario(){const campo=document.getElementById('cantidad-inventario');if(!campo||!Number.isFinite(Number(campo.value))||Number(campo.value)<=0){alert('La cantidad debe ser numérica y mayor que 0.');return false}return true}</script><?php require __DIR__.'/../../includes/footer.php';
